def verify_factory_identity(text, label, start, end):
    require(any((row[0], row[2], row[3]) == (label, start, end)
                for row in REVIEWS['factory-identity']), 'unreviewed factory identity window')
    count = validate_disassembly(text, start, end)
    rows = {int(address, 16): (op, re.sub(r'\s+', '', args.split(';')[0]))
            for address, op, args in re.findall(
                r'^.*\[0x([0-9a-fA-F]+)\]\s+<[^>]*>:[ \t]+(\S+)[ \t]*([^\n]*)', text, re.M)}
    anchors = FACTORY_IDENTITY_ANCHORS[label]
    require(all(rows.get(a) == pair for a, pair in anchors.items()),
            'factory identity structural anchors differ')
    return {'decoded_instructions': count, 'structural_anchors': len(anchors),
            'claim': 'file-only-factory-identity-not-runtime-receiver-or-registration-ABI'}


def verify_factory_table(words, fixups, chains, label):
    require(label == 'factory-primary-table', 'unreviewed factory table')
    _, _, start, count = DATA_WINDOWS['factory-identity'][0]
    formats = re.findall(r'pointer_format:\s+(\d+)\s+\(([^)]+)\)', chains)
    require(formats and all(pair == ('6', 'DYLD_CHAINED_PTR_64_OFFSET') for pair in formats),
            'factory table fixup format differs')
    require(len(words) == count and all(isinstance(w, int) and 0 <= w < 1 << 64 and
            not w & ((1 << 63) | (0x7fff << 36)) for w in words),
            'factory table coverage/bind/reserved bits differ')
    targets = tuple(w & ((1 << 36)-1) for w in words)
    require(targets == FACTORY_TABLE_TARGETS, 'factory table targets differ')
    rows = []
    for address, kind, target in re.findall(
            r'^\s*__DATA_CONST\s+__const\s+0x([0-9a-fA-F]+)\s+(\S+)\s+([^\n]+)', fixups, re.M):
        address = int(address, 16)
        if start <= address < start + count*8:
            require(kind == 'rebase' and re.fullmatch(r'0x[0-9a-fA-F]+', target.strip()),
                    'factory table fixup is not a plain rebase')
            rows.append((address, int(target.strip(), 16)))
    require(rows == [(start+i*8, target) for i, target in enumerate(targets)],
            'factory table fixups differ or are incomplete/duplicated')
    return {'rebases': count, 'file_targets': [hex(t) for t in targets],
            'claim': 'file-table-correspondence-not-runtime-receiver'}


